// ============================================================================
// [PLAIN-TEXT CHECKPOINT: ACCOUNTING TRANSACTION FORMATTER & G7n TABLE]
// Used by /zh-cn/headquarters/accounting/ to format cash flow descriptions.
// Resolves descriptionKey (e.g. salesOrderFulfilled, rocketExplosion) into i18n text.
// ============================================================================

function GUt(intl, transaction) {
  const { descriptionKey: key } = transaction;
  if (!key) {
    console.debug("[CHECKPOINT:ACCOUNTING_RAW_DESC] Fallback to raw description:", transaction.description);
    return transaction.description;
  }

  try {
    // 1. Personal Assistant (PA) transactions
    const paMsg = V7n[key];
    if (paMsg) return intl.formatMessage(paMsg);

    // 2. Main Accounting G7n Key-Value Table
    const mainMsg = G7n[key];
    if (mainMsg) {
      console.debug(`[CHECKPOINT:ACCOUNTING_DESC] Resolved key '${key}' via G7n`);
      return intl.formatMessage(mainMsg);
    }

    // 3. Dynamic Compound Transaction Keys (resource / amount / quality)
    if (ta(key, ut.BUY_ORDER_FILLED)) {
      const [resId, amount, quality] = UC(key, ut.BUY_ORDER_FILLED);
      return intl.formatMessage($r.buyOrderFilled, {
        resource: gt(intl, ku(resId)),
        amount: intl.formatNumber(parseInt(amount, 10), { maximumFractionDigits: 0 }),
        quality: parseInt(quality, 10)
      });
    }

    if (ta(key, ut.BUY_ORDER_POSTED)) {
      const [resId, amount, quality] = UC(key, ut.BUY_ORDER_POSTED);
      return intl.formatMessage($r.buyOrderPosted, {
        resource: gt(intl, ku(resId)),
        amount: intl.formatNumber(parseInt(amount, 10), { maximumFractionDigits: 0 }),
        quality: parseInt(quality, 10)
      });
    }

    if (ta(key, ut.BUY_ORDER_CANCELLED)) {
      const [resId, amount, quality] = UC(key, ut.BUY_ORDER_CANCELLED);
      return intl.formatMessage($r.buyOrderCancelled, {
        resource: gt(intl, ku(resId)),
        amount: intl.formatNumber(parseInt(amount, 10), { maximumFractionDigits: 0 }),
        quality: parseInt(quality, 10)
      });
    }

    if (ta(key, ut.GIFT_BASKET)) {
      return intl.formatMessage($r.giftBasket, { basket: qx(intl, es(key, ut.GIFT_BASKET)) });
    }
    if (ta(key, ut.RETAIL)) {
      return intl.formatMessage($r.retail, { resource: gt(intl, ku(es(key, ut.RETAIL))) });
    }
    if (ta(key, ut.LOSS_RETAIL)) return intl.formatMessage($r.inventoryLossRetail);
    if (ta(key, ut.PRODUCTION_REFUND)) return intl.formatMessage($r.productionRefund);
    if (ta(key, ut.PRODUCTION)) {
      return intl.formatMessage($r.production, { resource: gt(intl, ku(es(key, ut.PRODUCTION))) });
    }
    if (ta(key, ut.LAUNCH)) {
      return intl.formatMessage($r.launch, { resource: gt(intl, ku(es(key, ut.LAUNCH))) });
    }
    if (ta(key, ut.DEMOLITION)) {
      return intl.formatMessage($r.demolition, { building: Zi(intl, es(key, ut.DEMOLITION)) });
    }
    if (ta(key, ut.DEMOLITION_INSOLVENCY)) {
      return intl.formatMessage($r.demolitionInsolvency, { building: Zi(intl, es(key, ut.DEMOLITION_INSOLVENCY)) });
    }
    if (ta(key, ut.SEVERANCE)) {
      return intl.formatMessage($r.severance, { name: es(key, ut.SEVERANCE) });
    }
    if (ta(key, ut.CANCEL_FEE)) {
      return intl.formatMessage($r.cancelFee, { resource: gt(intl, ku(es(key, ut.CANCEL_FEE))) });
    }
    if (ta(key, ut.MARKET_FEES)) {
      return intl.formatMessage($r.marketFees, { resource: gt(intl, ku(es(key, ut.MARKET_FEES))) });
    }
    if (ta(key, ut.EXCHANGE)) {
      return intl.formatMessage($r.exchange, { simboosts: parseInt(es(key, ut.EXCHANGE), 10) });
    }
    if (ta(key, ut.ACHIEVEMENT)) {
      return intl.formatMessage($r.achievement, { achievement: es(key, ut.ACHIEVEMENT) });
    }
    if (ta(key, ut.TRAINING)) {
      const trainingId = es(key, ut.TRAINING);
      return intl.formatMessage($r.training, { training: intl.formatMessage(CO(trainingId)) });
    }
    if (ta(key, ut.EXECUTIVE_TRAINING_COST)) {
      return intl.formatMessage($r.executiveTrainingCost, { name: es(key, ut.EXECUTIVE_TRAINING_COST) });
    }
    if (ta(key, ut.EXECUTIVE_TRAINING_REIMBURSEMENT)) {
      return intl.formatMessage($r.executiveTrainingReimbursement, { name: es(key, ut.EXECUTIVE_TRAINING_REIMBURSEMENT) });
    }
    if (ta(key, ut.EXECUTIVE_SIGNUP_BONUS)) {
      return intl.formatMessage($r.executiveSignupBonus, { name: es(key, ut.EXECUTIVE_SIGNUP_BONUS) });
    }
    if (ta(key, ut.EXECUTIVE_AGENCY_FEES)) {
      return intl.formatMessage($r.executiveAgencyFees, { name: es(key, ut.EXECUTIVE_AGENCY_FEES) });
    }
    if (ta(key, ut.EXECUTIVE_TERMINATION_PACKAGE)) {
      return intl.formatMessage($r.executiveTerminationPackage, { name: es(key, ut.EXECUTIVE_TERMINATION_PACKAGE) });
    }
    if (ta(key, ut.EXECUTIVE_POACHED)) {
      return intl.formatMessage($r.executivePoached, { name: es(key, ut.EXECUTIVE_POACHED) });
    }
    if (ta(key, ut.EXECUTIVE_POACHING_BONUS)) {
      return intl.formatMessage($r.executivePoachingBonus, { name: es(key, ut.EXECUTIVE_POACHING_BONUS) });
    }
    if (ta(key, ut.EXECUTIVE_POACHING_FEE)) {
      return intl.formatMessage($r.executivePoachingFee, { name: es(key, ut.EXECUTIVE_POACHING_FEE) });
    }
    if (ta(key, ut.EXECUTIVE_STRIKE_EXPENSES)) {
      return intl.formatMessage($r.executiveStrikeExpenses, { name: es(key, ut.EXECUTIVE_STRIKE_EXPENSES) });
    }
    if (ta(key, ut.ROBOTS)) {
      return intl.formatMessage($r.robots, { building: Zi(intl, es(key, ut.ROBOTS)) });
    }
    if (ta(key, ut.CONSTRUCTION)) {
      return intl.formatMessage($r.construction, { building: Zi(intl, es(key, ut.CONSTRUCTION)) });
    }
    if (ta(key, ut.UPGRADE)) {
      return intl.formatMessage($r.upgrade, { building: Zi(intl, es(key, ut.UPGRADE)) });
    }
    if (ta(key, ut.DOWNGRADE)) {
      return intl.formatMessage($r.downgrade, { building: Zi(intl, es(key, ut.DOWNGRADE)) });
    }

    console.warn(`[CHECKPOINT:ACCOUNTING_UNMAPPED_KEY] Unmapped key '${key}', fallback to description:`, transaction.description);
  } catch (err) {
    console.error("[CHECKPOINT:ACCOUNTING_ERROR] Unknown money transaction description key: " + key, err);
  }
  return transaction.description || key;
}

